    inside=set(int(v) for r in range(dr0,dr0+h) for c in range(dc0,dc0+w) if I[r,c]!=bc and I[r,c]!=m)
    cl=[(r,c,int(I[r,c])) for r in range(I.shape[0]) for c in range(I.shape[1])
        if I[r,c]!=bc and I[r,c]!=m and not(dr0<=r<=dr0+h-1 and dc0<=c<=dc0+w-1)]
    # determine shift: find pair (cluster cell, same-color inside cell) consistent for ALL such pairs
    shifts=[]
    for r,c,col in cl:
        if col in inside:
            for rr in range(dr0,dr0+h):
                for cc_ in range(dc0,dc0+w):
                    if int(I[rr,cc_])==col:
                        shifts.append(((r+c),(rr+cc_),rr-r,cc_-c))
    best=None
    from collections import Counter
    cand=Counter((dr_,dc_) for _,_,dr_,dc_ in shifts)
    dr0_,dc0_=cand.most_common(1)[0][0]
    for r,c,col in cl:
        nr,nc=r+dr0_,c+dc0_
        if 0<=nr<h and 0<=nc<w:
            out[nr,nc]=col
    return out.tolist()
