def solve(g):
    g=[r[:] for r in g]
    H,W=len(g),len(g[0])
    bg=max(Counter(x for r in g for x in r),key=lambda c:sum(r.count(c) for r in g))
    # frame: solid uniform non-bg color border of a rectangle; find largest such rect
    best=None
    for i1 in range(H):
        for j1 in range(W):
            c=g[i1][j1]
            if c==bg: continue
            for h in range(3,H-i1+1):
                if i1+h>=H: break
                for w in range(3,W-j1+1):
                    if j1+w>=W: break
                    sub=[[g[r][k] for k in range(j1,j1+w)] for r in range(i1,i1+h)]
                    if sub[0]==[c]*w and sub[-1]==[c]*w and all(sub[r][0]==c and sub[r][-1]==c for r in range(h)):
                        if best is None or h*w>best[0]: best=(h*w,i1,j1,h,w,c)
    _,i1,j1,hh,ww,fc_=best
    out=[[g[r][k] for k in range(j1,j1+ww)] for r in range(i1,i1+hh)]
    return out,bg,fc_
